const guides=[
{title:'SHIFT: выбирай смену до работы',category:'Заработок',text:'Обычные котировки — 80–120%, пересчёт раз в 15 минут. При ставке от 100% можно заключить контракт: фонд повышенной оплаты рассчитан на 40–90 минут. Ставки персональные — проверяй свой телефон.',url:sources.shift},
{title:'Рыбалка и охота: условия наряда',category:'Заработок',text:'Повышенная оплата распространяется на подходящую добычу, полученную после начала наряда. Нужно успеть сдать её до его окончания. Старые запасы и добыча вне списка не получают эту надбавку.',url:sources.shift},
{title:'Особые предложения SHIFT',category:'Заработок',text:'Горящий наряд может дать до 135%. Общая смена — 150%, пять мест, один раз в сутки на аккаунт. После отмены место не возвращается. Это предложения в игре, а не постоянно доступные ставки.',url:sources.shift},
{title:'Собери удочку под свою зону',category:'Рыбалка',text:'Нужны лицензия, удилище, катушка, леска и наживка. Магазин Сэнди-Шорс продаёт снасти 1–5 уровня; 6–10 доступны из кейсов и турниров. Удилище влияет на ожидание, катушка — на подтягивание, видимость лески — на редкость.',url:sources.fish},
{title:'Сравни скупщиков перед продажей',category:'Рыбалка',text:'Обычные скупщики: 80–105% базовой ценности. У Rednecks: 100–120%, нужен пятый ранг клуба. Цены пересчитываются раз в три часа. Кайо-Перико относится к зоне тропического рифа.',url:sources.fish},
{title:'Считай расходы на снасти',category:'Рыбалка',text:'Снасти изнашиваются, а наживки бывают одноразовыми и многоразовыми. В журнале учитывай наживку, использованную долю снастей, дорогу и аренду. Для сравнения работ дели чистую прибыль на всё затраченное время.',url:sources.fish},
{title:'Как прокачивать кулинарию',category:'Кулинария',text:'Пороги опыта по уровням: 50 → 100 → 150 → 200 → 250. Приготовление даёт 1–4 опыта. Простое соединение уже готовых компонентов не начисляет опыт. Более сложные блюда требуют повышенного навыка.',url:sources.skills},
{title:'Цена упаковки — не цена штуки',category:'Кулинария',text:'В магазинах ингредиенты часто продаются упаковками по 10. Делите цену упаковки на количество перед расчётом блюда. Наценку задаёт владелец магазина, поэтому в калькуляторе нужны ваши фактические цены.',url:sources.shops}
];
